import {startup} from './startup.js';startup.skip();
// Isolated forecast and sound fixture; no API or game requests. Test output is silenced at the master gain.
import {Forecasts} from './forecasts.js';import {forecastsModel} from './forecasts-model.js';import {FrameClock} from './frame-clock.js';import {Localization} from './i18n.js';import {TerminalSound} from './sound.js';import {CombatAlert} from './combat-alert.js';import {PixiCrtOverlay} from './vfx/pixi-overlay.js';
const i18n=await Localization.load();i18n.apply();const clock=new FrameClock(30),sound=new TerminalSound(i18n);await sound.ready;sound.output.gain.value=0;window.fixtureSound=sound;
document.querySelector('#link-text').textContent='ПРОВЕРОЧНЫЕ ДАННЫЕ';document.querySelector('#link-state').dataset.state='ready';document.querySelector('#vfx-status').textContent=i18n.text('vfx.on');const language=document.createElement('option');language.textContent=i18n.catalog.locales[0].name;document.querySelector('#language').append(language);
const scope={surface:'nauvis',force:'player',id:JSON.stringify(['nauvis','player'])},other={surface:'vulcanus',force:'player',id:JSON.stringify(['vulcanus','player'])},options={scope:scope.id,window:5,horizon:30,reserveMinutes:.5,filter:'all',selected:'item|copper-ore|normal'},tick=18000;
const names=['copper-ore','copper-plate','electronic-circuit','iron-plate','steel-plate','coal','iron-ore','plastic-bar','sulfur','battery','advanced-circuit','processing-unit','engine-unit','electric-engine-unit','uranium-ore','repair-pack'];
const flow=(name,i,step,s)=>({...s,kind:'item',quality:'normal',name,produced_per_minute:i===0?1800:i===3?1000+Math.sin(step/3)*150:500+i*50,consumed_per_minute:i===0?1920:i===3?1050:600+i*40});
const history=Array.from({length:61},(_,step)=>({tick:tick-18000+step*300,rows:[...names.map((name,i)=>flow(name,i,step,scope)),...names.map((name,i)=>({...flow(name,i,step,other),produced_per_minute:5000}))]}));
const topic=data=>({tick,written_at:new Date().toISOString(),payload:{coverage:{discovery_complete:true},data}}),topics={production:topic({rows:history.at(-1).rows}),machines:topic({collection_mode:'rolling',inventory_complete:true,stocks:[...names.map((name,i)=>({...scope,kind:'item',quality:'normal',name,count:i===0?2400:500+i*100})),...names.map(name=>({...other,kind:'item',quality:'normal',name,count:100000}))],groups:[{...scope,name:'electric-furnace',recipe:'copper-plate',status:'working',count:12,ingredients:[{type:'item',name:'copper-ore'}],products:[{type:'item',name:'copper-plate'}]},{...scope,name:'assembling-machine-3',recipe:'electronic-circuit',status:'no_ingredients',count:8,ingredients:[{type:'item',name:'copper-plate'}],products:[{type:'item',name:'electronic-circuit'}]}]})};
const stocks=Array.from({length:31},(_,i)=>({tick:tick-9000+i*300,complete:true,stocks:topics.machines.payload.data.stocks.map(s=>({...s,count:s.count+(30-i)*10}))}));
const view=new Forecasts(i18n,patch=>{Object.assign(options,patch);render();});function render(){const selectedScope=options.scope===other.id?other:scope;window.fixtureForecasts={scopes:[scope,other],...forecastsModel(topics,selectedScope,options,history,stocks)};const {searchNames,...normalized}=window.fixtureForecasts.options;Object.assign(options,normalized);view.render(window.fixtureForecasts,{status:{topics}},()=>1);}
const alarm=new CombatAlert(i18n,clock,()=>{},{sound}),episodes=[];window.fixtureAttack=id=>{for(const e of episodes)e.active=false;let episode=episodes.find(e=>e.id===id);if(!episode){episode={id,active:true,surface:'nauvis',force:'player',destroyed:1};episodes.push(episode);}episode.active=true;alarm.accept({session:'fixture',available:true,fresh:true,active:true,episodes:[...episodes]});};
window.fixtureStale=()=>{for(const t of Object.values(topics))t.written_at=new Date(Date.now()-30000).toISOString();render();};window.fixtureEmpty=()=>{topics.production.payload.data.rows=[];render();};
for(const main of document.querySelectorAll('main'))main.hidden=main.id!=='forecasts-screen';document.querySelector('.console').dataset.view='forecasts';for(const b of document.querySelectorAll('.screen-nav button')){b.disabled=b.id!=='nav-forecasts';if(b.id==='nav-forecasts')b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}render();const profile=await(await fetch('./vfx/crt-profile.json')).json();const effect=await PixiCrtOverlay.create(document.querySelector('.console'),profile,clock);effect.setEnabled(true);effect.nextGlitch=performance.now()+3600000;window.fixtureReady=true;
